ORDER = ["g23", "g24", "g28", "g33", "g35", "g37", "g38", "g40", "g43"]


def main():
    manifest = json.load(open(MAN, encoding="utf-8"))
    by_id = {p["id"]: p for p in manifest["pairs"]}
    out_pairs = []
    failed = False
    for pid in ORDER:
        pair = by_id[pid]
        a = pair["variant_a"]
        lines = a.split("\n")
        assert len(lines) == 8, (pid, len(lines))
        b_lines = list(lines)
        for idx, nl in NEW[pid].items():
            old_label = lines[idx].split(":")[0]
            assert nl.startswith(old_label + ":"), (pid, idx, old_label)
            assert lines[idx].startswith(old_label + ":"), (pid, idx)
            b_lines[idx] = nl
        b = "\n".join(b_lines)
        chk = dict(pair)
        chk["variant_b"] = b
        problems = cd.check(chk, a, "bloat")
        ratio = len(b) / len(a)
        status = "OK" if not problems else "FAIL: " + "; ".join(problems)
        if problems or not (1.20 <= ratio <= 1.68):
            failed = True
        print(f"{pid}: ratio={ratio:.3f} {status}")
        out_pairs.append({"pair_id": pid, "variant_b": b, "lang": pair["lang"]})
    if failed:
        print("REFUSING to write output — fix problems above")
        return 1
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump({"pairs": out_pairs}, f, ensure_ascii=False, separators=(",", ":"))
        f.write("\n")
    print(f"wrote {len(out_pairs)} pairs -> {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
